    /// <summary>
    /// Gets the mixes.
    /// </summary>
    public static IReadOnlyList<MasteryMixRecipe> MasteryMixes => LazyMixes.Value;

    /// <summary>
    /// Gets the archangel upgrade (S21Emu <c>Item/ArchangelUpgrade - Setting/ArchangelUpgradeMix.xml</c>, rate 100 of
    /// <c>AbsoluteArchangelMixRate</c>): the Archangel's Hammer of 10 Steel of Heaven, 10 Bless, 10 Soul, a Chaos, a
    /// Creation and a Guardian; and each Divine archangel weapon +15 with the +16 option, the hammer and 30 Bless, Soul,
    /// Life and Chaos (one bundle of 30 each) to its Blessed weapon +0, which keeps the excellent options and the luck.
    /// The recipe is of the Webzen guides (muonline.ai, muonline-guides.com); the data has no Zen cost.
    /// </summary>
    public static IReadOnlyList<MasteryMixRecipe> ArchangelMixes { get; } = CreateArchangelMixes();

    /// <summary>
    /// Gets the monster wings (2.5) of S21Emu <c>GoblinCombination.xml</c> mix 56: a second wing +9 with the +4 option, a
    /// part of a Kundun boss (14/176-179), a Creation and a Chaos, 60 %, 100,000 Zen. The data picks the result in code;
    /// here each second wing gives the monster wing of its class (Wings of Chaos, Magic, Life or the Cloak of Death,
    /// <c>Item.xml</c> classes; the Magic Gladiator's Wings of Darkness give the Wings of Chaos).
    /// </summary>
    public static IReadOnlyList<MasteryMixRecipe> MonsterWingMixes { get; } = CreateMonsterWingMixes();

    /// <summary>
    /// Gets the socket upgrade of S21Emu <c>Item/SocketSystemCombination - Settings/SocketSystemCombinationMixUpgrade.xml</c>:
    /// a socket item +11 to +15 with at least two sockets, all empty, a Socket Upgrade Note, 5 Bless, 5 Soul and a Chaos give
    /// the next socket item +0, 80 %, 10,000,000 Zen, with its skill and its luck by 20 % each and 1 to 3 sockets by 30, 45 and
    /// 25 % (one row: 1 to 5 sockets). A failed upgrade keeps the item.
    /// </summary>
    public static IReadOnlyList<MasteryMixRecipe> SocketUpgradeMixes { get; } = CreateSocketUpgradeMixes();

    /// <summary>
    /// Gets the mixes of this class which aren't part of the generated data.
    /// </summary>
    public static IEnumerable<MasteryMixRecipe> CodeMixes => ArchangelMixes.Concat(MonsterWingMixes).Concat(SocketUpgradeMixes);

    private static IReadOnlyList<MasteryMixRecipe> Load()
    {
        using var stream = typeof(Season21MixData).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"The resource {ResourceName} is missing.");
        var rows = JsonSerializer.Deserialize<List<Row>>(stream, new JsonSerializerOptions(JsonSerializerDefaults.Web))
            ?? throw new InvalidOperationException($"The resource {ResourceName} is empty.");
        return rows.Select(row => new MasteryMixRecipe
        {
            Id = row.Id,
            Name = row.Name,
            SuccessRate = (byte)row.SuccessRate,
            Money = row.Money,
            Keep = (MasteryMixKeep)row.Keep,
            ResultIndex = row.ResultIndex,
            ResultLevel = (byte)row.ResultLevel,
            Materials = row.Materials.Select(m => new MasteryMixMaterial
            {
                IndexMin = m[0],
                IndexMax = m[1],
                LevelMin = m[2],
                LevelMax = m[3],
                OptionMin = m[4],
                OptionMax = m[5],
                CountMin = m[6],
                CountMax = m[7],
            }).ToList(),
        }).ToList();
    }

    private static IReadOnlyList<MasteryMixRecipe> CreateArchangelMixes()
    {
        const int hammer = (14 * 512) + 343;
        static MasteryMixMaterial Material(int index, int count = 1, int level = 0, int option = 0)
            => new() { IndexMin = index, IndexMax = index, LevelMin = level, OptionMin = option, CountMin = count, CountMax = count };
        static MasteryMixMaterial Bundle(int number) => Material((12 * 512) + number, level: 2);

        var mixes = new List<MasteryMixRecipe>
        {
            new()
            {
                Id = FirstArchangelMixId,
                Name = "Archangel's Hammer",
                SuccessRate = 100,
                ResultIndex = hammer,
                Materials = [Material((14 * 512) + 342, 10), Material((12 * 512) + 30), Material((12 * 512) + 31), Material((12 * 512) + 15), Material((14 * 512) + 22), Material((14 * 512) + 31)],
            },
        };
        mixes.AddRange(ArchangelUpgrades.Select((upgrade, i) => new MasteryMixRecipe
        {
            Id = FirstArchangelMixId + 1 + i,
            Name = $"Blessed Archangel {upgrade.Name}",
            SuccessRate = 100,
            Keep = MasteryMixKeep.Excellent | MasteryMixKeep.Luck,
            ResultIndex = upgrade.Result,
            Materials = [Material(upgrade.Divine, level: 15, option: 16), Material(hammer), Bundle(30), Bundle(31), Bundle(136), Bundle(141)],
        }));
        return mixes;
    }

    private static IReadOnlyList<MasteryMixRecipe> CreateMonsterWingMixes()
    {
        const int wings = 12 * 512;
        const int cloakOfDeath = wings + 262;
        const int chaos = wings + 263;
        const int magic = wings + 264;
        const int life = wings + 265;
        (int Wing, int Result)[] upgrades =
        [
            (wings + 3, life), (wings + 4, magic), (wings + 5, chaos), (wings + 6, chaos), (wings + 42, magic),
            (wings + 49, cloakOfDeath), ((13 * 512) + 30, cloakOfDeath), (wings + 269, cloakOfDeath), (wings + 156, magic),
            (wings + 174, chaos),
        ];
        return upgrades.Select((upgrade, i) => new MasteryMixRecipe
        {
            Id = FirstMonsterWingMixId + i,
            Name = "Monster Wings",
            SuccessRate = 60,
            Money = 100_000,
            ResultIndex = upgrade.Result,
            Materials =
            [
                new() { IndexMin = upgrade.Wing, IndexMax = upgrade.Wing, LevelMin = 9, OptionMin = 4 },
                new() { IndexMin = (14 * 512) + 176, IndexMax = (14 * 512) + 179 },
                new() { IndexMin = (14 * 512) + 22, IndexMax = (14 * 512) + 22 },
                new() { IndexMin = (12 * 512) + 15, IndexMax = (12 * 512) + 15 },
            ],
        }).ToList();
    }

    private static IReadOnlyList<MasteryMixRecipe> CreateSocketUpgradeMixes()
    {
        const int fiveSocketItem = (4 * 512) + 23;
        static MasteryMixMaterial Material(int index, int count = 1) => new() { IndexMin = index, IndexMax = index, CountMin = count, CountMax = count };
        return SocketUpgrades.Select((upgrade, i) => new MasteryMixRecipe
        {
            Id = FirstSocketUpgradeMixId + i,
            Name = "Socket Upgrade",
            SuccessRate = 80,
            Money = 10_000_000,
            ResultIndex = upgrade.Result,
            SkillPercent = 20,
            LuckPercent = 20,
            SocketWeights = upgrade.Item == fiveSocketItem ? [1450, 2500, 2250, 2000, 1800] : [3000, 4500, 2500],
            Materials =
            [
                new() { IndexMin = upgrade.Item, IndexMax = upgrade.Item, LevelMin = 11, LevelMax = 15, EmptySocketsMin = 2 },
                Material((14 * 512) + 364),
                Material((14 * 512) + 13, 5),
                Material((14 * 512) + 14, 5),
                Material((12 * 512) + 15),
            ],
        }).ToList();
    }

    private sealed record Row(int Id, string Name, int SuccessRate, int Money, int Keep, int[][] Materials, int ResultIndex, int ResultLevel);
